style.css:
@-moz-document domain("youtube.com") {
/* =========================================================
       PALETTE
       ========================================================= */

    html {
        --gs-bg: #070807;
        --gs-bg-2: #090b09;
        --gs-panel: #0c0e0c;
        --gs-panel-2: #101210;
        --gs-panel-hover: #141714;

        --gs-border: #1b1e1b;
        --gs-border-light: #242824;

        --gs-green: #91c24b;
        --gs-green-light: #a3d55d;
        --gs-green-dark: #658d31;

        --gs-text: #ededed;
        --gs-text-2: #b8bcb8;
        --gs-muted: #747a74;

        --gs-glow: rgba(145, 194, 75, .18);

        /* YouTube variables */
        --yt-spec-base-background: #070807 !important;
        --yt-spec-raised-background: #0c0e0c !important;
        --yt-spec-menu-background: #0c0e0c !important;
        --yt-spec-inverted-background: #ededed !important;

        --yt-spec-text-primary: #ededed !important;
        --yt-spec-text-secondary: #989d98 !important;

        --yt-spec-general-background-a: #070807 !important;
        --yt-spec-general-background-b: #090b09 !important;
        --yt-spec-general-background-c: #0c0e0c !important;

        --yt-spec-brand-background-primary: #070807 !important;
        --yt-spec-brand-background-secondary: #090b09 !important;

        --yt-spec-badge-chip-background: #111311 !important;
        --yt-spec-10-percent-layer: rgba(255,255,255,.05) !important;
    }


    /* =========================================================
       GLOBAL
       ========================================================= */

    html,
    body,
    ytd-app {
        background: var(--gs-bg) !important;
        color: var(--gs-text) !important;
    }

    body {
        background-image:
            radial-gradient(
                ellipse 70% 30% at 50% -10%,
                rgba(145,194,75,.025),
                transparent 70%
            ) !important;

        background-attachment: fixed !important;
    }


    /* =========================================================
       TOP HEADER
       ========================================================= */

    #masthead-container,
    ytd-masthead,
    #container.ytd-masthead {

        background: rgba(7,8,7,.97) !important;

        border-bottom:
            1px solid var(--gs-border) !important;

        box-shadow:
            0 8px 30px rgba(0,0,0,.25) !important;

        backdrop-filter: blur(12px) !important;
    }


    /* =========================================================
       YOUTUBE LOGO
       Делаем оригинальный красный логотип зелёным
       ========================================================= */

    ytd-topbar-logo-renderer #logo-icon svg path,
    #youtube-paths path {

        transition:
            fill .2s ease !important;
    }

    /* Красная часть YouTube logo */

    ytd-topbar-logo-renderer svg path[fill="#FF0000"],
    ytd-topbar-logo-renderer svg path[fill="#f00"] {

        fill: var(--gs-green) !important;
    }


    /* =========================================================
       SEARCH BAR
       ========================================================= */

    #search-form.ytd-searchbox {

        background: #090b09 !important;

        border:
            1px solid #242824 !important;

        border-radius:
            22px 0 0 22px !important;

        box-shadow:
            inset 0 1px 3px rgba(0,0,0,.5) !important;
    }


    #search-input.ytd-searchbox {

        color: var(--gs-text) !important;
    }


    ytd-searchbox[has-focus] #search-form.ytd-searchbox {

        border-color:
            rgba(145,194,75,.55) !important;

        box-shadow:
            0 0 0 1px rgba(145,194,75,.12),
            0 0 10px rgba(145,194,75,.07) !important;
    }


    #search-icon-legacy.ytd-searchbox {

        background: #101210 !important;

        border:
            1px solid #242824 !important;

        border-left: none !important;
    }


    #search-icon-legacy.ytd-searchbox:hover {

        background: #151815 !important;
    }


    /* Search icon */

    #search-icon-legacy:hover yt-icon {

        color: var(--gs-green) !important;
    }


    /* =========================================================
       SIDEBAR
       ========================================================= */

    #guide-content,
    ytd-guide-renderer,
    ytd-mini-guide-renderer {

        background:
            var(--gs-bg) !important;
    }


    ytd-guide-entry-renderer {

        border-radius:
            10px !important;

        margin:
            2px 8px !important;
    }


    ytd-guide-entry-renderer:hover {

        background:
            var(--gs-panel-hover) !important;
    }


    /* Selected sidebar item */

    ytd-guide-entry-renderer[active] {

        background:
            #11150e !important;
    }


    ytd-guide-entry-renderer[active] yt-icon {

        color:
            var(--gs-green) !important;

        filter:
            drop-shadow(0 0 4px rgba(145,194,75,.22));
    }


    ytd-guide-entry-renderer[active] #endpoint {

        color:
            var(--gs-green-light) !important;
    }


    /* =========================================================
       CATEGORY CHIPS
       ========================================================= */

    yt-chip-cloud-chip-renderer,
    yt-chip-cloud-chip-renderer[chip-style="STYLE_DEFAULT"] {

        background:
            #111311 !important;

        border:
            1px solid #1d211d !important;

        color:
            #d8dad8 !important;

        box-shadow:
            none !important;

        transition:
            all .15s ease !important;
    }


    yt-chip-cloud-chip-renderer:hover {

        background:
            #171a17 !important;

        border-color:
            #303630 !important;
    }


    /* Selected category */

    yt-chip-cloud-chip-renderer[selected] {

        background:
            var(--gs-green) !important;

        color:
            #070807 !important;

        border-color:
            var(--gs-green) !important;

        box-shadow:
            0 0 9px rgba(145,194,75,.13) !important;
    }


    /* =========================================================
       VIDEO CARDS
       ========================================================= */

    ytd-rich-item-renderer,
    ytd-video-renderer,
    ytd-grid-video-renderer {

        border-radius:
            12px !important;
    }


    ytd-thumbnail {

        overflow:
            hidden !important;

        border-radius:
            10px !important;

        transition:
            filter .2s ease,
            transform .2s ease !important;
    }


    ytd-rich-item-renderer:hover ytd-thumbnail {

        filter:
            brightness(1.04) !important;
    }


    /* Video titles */

    #video-title {

        color:
            #e5e7e5 !important;
    }


    #video-title:hover {

        color:
            #f4f5f4 !important;
    }


    /* Metadata */

    #metadata-line,
    #metadata-line span,
    ytd-video-meta-block #byline-container {

        color:
            #7f857f !important;
    }


    /* =========================================================
       THUMBNAIL TIME
       ========================================================= */

    ytd-thumbnail-overlay-time-status-renderer {

        background:
            rgba(5,6,5,.90) !important;

        border:
            1px solid rgba(255,255,255,.05) !important;

        color:
            #eee !important;

        border-radius:
            5px !important;
    }


    /* =========================================================
       WATCH PAGE
       ========================================================= */

    ytd-watch-flexy,
    #columns,
    #primary,
    #secondary {

        background:
            transparent !important;
    }


    /* =========================================================
       VIDEO PLAYER
       ========================================================= */

    #movie_player {

        box-shadow:
            0 6px 30px rgba(0,0,0,.55) !important;
    }


    /* =========================================================
       PROGRESS BAR
       RED -> GAMESENSE GREEN
       ========================================================= */

    .ytp-play-progress {

        background:
            var(--gs-green) !important;

        box-shadow:
            0 0 6px rgba(145,194,75,.25) !important;
    }


    .ytp-scrubber-button {

        background:
            var(--gs-green-light) !important;

        box-shadow:
            0 0 8px rgba(145,194,75,.30) !important;
    }


    .ytp-load-progress {

        background:
            rgba(255,255,255,.18) !important;
    }


    /* =========================================================
       PLAYER CONTROLS
       ========================================================= */

    .ytp-button:hover svg {

        filter:
            drop-shadow(0 0 3px rgba(145,194,75,.30));
    }


    /* =========================================================
       BUTTONS UNDER VIDEO
       ========================================================= */

    ytd-watch-metadata
    yt-button-shape button,

    ytd-menu-renderer
    yt-button-shape button {

        background:
            #111311 !important;

        color:
            #e1e3e1 !important;

        border:
            1px solid #1d211d !important;

        box-shadow:
            none !important;
    }


    ytd-watch-metadata
    yt-button-shape button:hover,

    ytd-menu-renderer
    yt-button-shape button:hover {

        background:
            #171a17 !important;

        border-color:
            #303630 !important;
    }


    /* =========================================================
       SUBSCRIBE BUTTON
       ========================================================= */

    ytd-subscribe-button-renderer
    yt-button-shape button {

        background:
            var(--gs-green) !important;

        color:
            #070807 !important;

        border:
            none !important;

        font-weight:
            600 !important;

        box-shadow:
            0 0 10px rgba(145,194,75,.13) !important;

        transition:
            all .15s ease !important;
    }


    ytd-subscribe-button-renderer
    yt-button-shape button:hover {

        background:
            var(--gs-green-light) !important;

        box-shadow:
            0 0 14px rgba(145,194,75,.20) !important;
    }


    /* =========================================================
       DESCRIPTION
       ========================================================= */

    #description.ytd-watch-metadata {

        background:
            #0e100e !important;

        border:
            1px solid var(--gs-border) !important;

        border-radius:
            12px !important;
    }


    #description.ytd-watch-metadata:hover {

        background:
            #111311 !important;
    }


    /* =========================================================
       COMMENTS
       ========================================================= */

    ytd-comment-thread-renderer {

        border-bottom:
            1px solid rgba(255,255,255,.035) !important;

        padding-bottom:
            10px !important;
    }


    ytd-comment-renderer #content-text {

        color:
            #d8dad8 !important;
    }


    ytd-comment-renderer #author-text {

        color:
            #b9bdb9 !important;
    }


    /* Comment input */

    ytd-comment-simplebox-renderer
    #placeholder-area {

        color:
            #6d726d !important;

        border-bottom-color:
            #292d29 !important;
    }


    /* =========================================================
       MENUS / POPUPS
       ========================================================= */

    ytd-menu-popup-renderer,
    tp-yt-paper-dialog,
    ytd-popup-container tp-yt-paper-listbox,
    yt-sheet-view-model {

        background:
            #0c0e0c !important;

        border:
            1px solid #202420 !important;

        box-shadow:
            0 12px 35px rgba(0,0,0,.60) !important;

        border-radius:
            12px !important;
    }


    tp-yt-paper-item:hover,
    ytd-menu-service-item-renderer:hover {

        background:
            #141714 !important;
    }


    /* =========================================================
       TOOLTIP
       ========================================================= */

    tp-yt-paper-tooltip {

        --paper-tooltip-background:
            #151815 !important;

        --paper-tooltip-text-color:
            #e4e6e4 !important;
    }


    /* =========================================================
       SHORTS
       ========================================================= */

    ytd-reel-video-renderer {

        background:
            #070807 !important;
    }


    ytd-reel-video-renderer
    #actions button {

        background:
            rgba(15,18,15,.90) !important;

        border:
            1px solid #252925 !important;
    }


    ytd-reel-video-renderer
    #actions button:hover {

        background:
            #181c18 !important;
    }


    /* =========================================================
       NOTIFICATIONS
       ========================================================= */

    ytd-notification-renderer {

        border-bottom:
            1px solid #181b18 !important;
    }


    ytd-notification-renderer:hover {

        background:
            #101310 !important;
    }


    /* =========================================================
       SCROLLBAR
       ========================================================= */

    ::-webkit-scrollbar {

        width:
            8px !important;

        height:
            8px !important;
    }


    ::-webkit-scrollbar-track {

        background:
            #070807 !important;
    }


    ::-webkit-scrollbar-thumb {

        background:
            #252925 !important;

        border-radius:
            10px !important;

        border:
            2px solid #070807 !important;
    }


    ::-webkit-scrollbar-thumb:hover {

        background:
            #465437 !important;
    }


    /* =========================================================
       TEXT SELECTION
       ========================================================= */

    ::selection {

        background:
            rgba(145,194,75,.25) !important;

        color:
            #fff !important;
    }


    /* =========================================================
       LINKS
       ========================================================= */

    a:hover {

        text-decoration-color:
            var(--gs-green) !important;
    }


    /* =========================================================
       FOCUS
       ========================================================= */

    button:focus-visible,
    a:focus-visible {

        outline:
            1px solid rgba(145,194,75,.48) !important;

        outline-offset:
            2px !important;
    }


    /* =========================================================
       LOADING / SPINNER
       ========================================================= */

    tp-yt-paper-spinner-lite {

        --paper-spinner-color:
            var(--gs-green) !important;
    }


    /* =========================================================
       PLAYLIST PANELS
       ========================================================= */

    ytd-playlist-panel-renderer {

        background:
            #0b0d0b !important;

        border:
            1px solid var(--gs-border) !important;

        border-radius:
            12px !important;
    }


    ytd-playlist-panel-video-renderer:hover {

        background:
            #121512 !important;
    }


    ytd-playlist-panel-video-renderer[selected] {

        background:
            #11150e !important;

        border-left:
            2px solid var(--gs-green) !important;
    }


    /* =========================================================
       LIVE CHAT
       ========================================================= */

    yt-live-chat-renderer,
    yt-live-chat-header-renderer,
    yt-live-chat-message-input-renderer {

        background:
            #0b0d0b !important;
    }


    yt-live-chat-text-message-renderer:hover {

        background:
            #111311 !important;
    }


    /* =========================================================
       GREEN ACCENTS
       ========================================================= */

    ytd-guide-entry-renderer[active] yt-icon,
    yt-chip-cloud-chip-renderer[selected] yt-icon {

        color:
            var(--gs-green) !important;
    }


    /* =========================================================
       DON'T OVERDO GREEN
       ========================================================= */

    /*
       Основные поверхности специально остаются почти чёрными.
       Green используется только:
       - active navigation
       - selected chips
       - subscribe
       - player progress
       - focus / hover details
    */
/* =========================================================
   GAMESENSE V2 — STRONG OVERRIDES
   ДОБАВИТЬ В КОНЕЦ СТИЛЯ
   ========================================================= */


/* ---------- ГЛАВНЫЙ ФОН ---------- */

html,
body,
ytd-app,
#content.ytd-app,
#page-manager,
ytd-browse,
ytd-two-column-browse-results-renderer,
ytd-rich-grid-renderer {
    background: #060706 !important;
}


/* ---------- ШАПКА ---------- */

ytd-masthead,
#masthead-container,
#container.ytd-masthead {
    background: #080908 !important;
    border-bottom: 1px solid #181c18 !important;

    box-shadow:
        0 5px 22px rgba(0,0,0,.55) !important;
}


/* ---------- ЛЕВАЯ ПАНЕЛЬ ---------- */

ytd-guide-renderer,
#guide-content.ytd-app,
#guide-inner-content,
ytd-mini-guide-renderer {
    background: #070807 !important;
}


/* обычные пункты */

ytd-guide-entry-renderer #endpoint {
    border-radius: 9px !important;

    transition:
        background .15s ease,
        color .15s ease !important;
}

ytd-guide-entry-renderer #endpoint:hover {
    background: #111411 !important;
}


/* активная Главная */

ytd-guide-entry-renderer[active] #endpoint {
    background: #10160d !important;

    box-shadow:
        inset 3px 0 0 #91c24b !important;
}


/* активная иконка */

ytd-guide-entry-renderer[active] yt-icon {
    color: #91c24b !important;

    filter:
        drop-shadow(0 0 4px rgba(145,194,75,.3));
}


/* текст активного пункта */

ytd-guide-entry-renderer[active] yt-formatted-string {
    color: #a5d85e !important;
}


/* ---------- РАЗДЕЛИТЕЛИ SIDEBAR ---------- */

ytd-guide-section-renderer {
    border-bottom-color: #191c19 !important;
}


/* =========================================================
   SEARCH
   ========================================================= */

ytd-searchbox #container,
ytd-searchbox #search-form,
#search-form.ytd-searchbox {
    background: #0b0d0b !important;

    border-color: #242824 !important;

    box-shadow:
        inset 0 1px 4px rgba(0,0,0,.5) !important;
}


ytd-searchbox[has-focus] #container,
ytd-searchbox[has-focus] #search-form {
    border-color: #587832 !important;

    box-shadow:
        0 0 0 1px rgba(145,194,75,.15),
        0 0 12px rgba(145,194,75,.07) !important;
}


/* кнопка поиска */

#search-icon-legacy {
    background: #111311 !important;

    border-color: #242824 !important;
}

#search-icon-legacy:hover {
    background: #171a17 !important;
}

#search-icon-legacy:hover yt-icon {
    color: #9bd052 !important;
}


/* =========================================================
   КАТЕГОРИИ СВЕРХУ
   ========================================================= */

yt-chip-cloud-chip-renderer,
yt-chip-cloud-chip-renderer[chip-style],
yt-chip-cloud-chip-renderer[chip-style="STYLE_DEFAULT"] {

    background: #121412 !important;

    border: 1px solid #1f231f !important;

    color: #c7cac7 !important;

    box-shadow:
        inset 0 1px 0 rgba(255,255,255,.025) !important;

    border-radius: 7px !important;
}


/* hover */

yt-chip-cloud-chip-renderer:hover {
    background: #191c19 !important;

    border-color: #303630 !important;
}


/* выбранное "Все" */

yt-chip-cloud-chip-renderer[selected],
yt-chip-cloud-chip-renderer[aria-selected="true"] {

    background: #91c24b !important;

    color: #060706 !important;

    border-color: #91c24b !important;

    box-shadow:
        0 0 10px rgba(145,194,75,.18) !important;
}

yt-chip-cloud-chip-renderer[selected] *,
yt-chip-cloud-chip-renderer[aria-selected="true"] * {
    color: #060706 !important;
}


/* =========================================================
   НОВЫЕ YOUTUBE CHIPS
   ========================================================= */

yt-chip-cloud-chip-renderer yt-formatted-string {
    color: inherit !important;
}

yt-chip-cloud-renderer {
    background: #060706 !important;
}


/* =========================================================
   ВИДЕО
   ========================================================= */

ytd-rich-item-renderer {
    border-radius: 12px !important;

    transition:
        transform .18s ease !important;
}


/* превью */

ytd-thumbnail,
yt-thumbnail-view-model {

    border-radius: 11px !important;

    overflow: hidden !important;

    transition:
        filter .18s ease,
        box-shadow .18s ease !important;
}


/* hover видео */

ytd-rich-item-renderer:hover ytd-thumbnail,
ytd-rich-item-renderer:hover yt-thumbnail-view-model {

    filter:
        brightness(1.05) !important;

    box-shadow:
        0 0 0 1px rgba(145,194,75,.22),
        0 8px 25px rgba(0,0,0,.45) !important;
}


/* название */

#video-title,
yt-lockup-metadata-view-model h3,
yt-lockup-metadata-view-model a {

    transition:
        color .15s ease !important;
}


ytd-rich-item-renderer:hover #video-title {
    color: #a6d65f !important;
}


/* metadata */

#metadata-line span,
#metadata-line,
ytd-video-meta-block,
yt-content-metadata-view-model {

    color: #777d77 !important;
}


/* =========================================================
   КНОПКА СОЗДАТЬ
   ========================================================= */

ytd-button-renderer button,
yt-button-shape button {

    transition:
        background .15s ease,
        border-color .15s ease,
        color .15s ease !important;
}


/* create */

ytd-masthead yt-button-shape button {

    background: #111311 !important;

    border:
        1px solid #202420 !important;

    color: #e1e3e1 !important;
}


ytd-masthead yt-button-shape button:hover {

    background: #161a15 !important;

    border-color: #465a31 !important;
}


/* =========================================================
   POPUPS
   ========================================================= */

tp-yt-paper-dialog,
ytd-menu-popup-renderer,
tp-yt-paper-listbox,
yt-sheet-view-model,
ytd-multi-page-menu-renderer {

    background: #0b0d0b !important;

    border:
        1px solid #202420 !important;

    box-shadow:
        0 15px 45px rgba(0,0,0,.7) !important;

    border-radius:
        12px !important;
}


/* элементы меню */

tp-yt-paper-item:hover,
ytd-menu-service-item-renderer:hover {

    background: #141714 !important;
}


/* =========================================================
   VIDEO PAGE
   ========================================================= */

ytd-watch-flexy,
#columns,
#primary,
#secondary {

    background: #060706 !important;
}


/* описание */

#description.ytd-watch-metadata,
ytd-text-inline-expander {

    background: #0d0f0d !important;

    border:
        1px solid #1b1f1b !important;

    border-radius:
        12px !important;
}


/* =========================================================
   КНОПКИ ПОД ВИДЕО
   ========================================================= */

ytd-watch-metadata
yt-button-shape button,

ytd-menu-renderer
yt-button-shape button {

    background: #111311 !important;

    border:
        1px solid #1e221e !important;

    color: #dedfde !important;
}


ytd-watch-metadata
yt-button-shape button:hover,

ytd-menu-renderer
yt-button-shape button:hover {

    background: #171a17 !important;

    border-color: #384138 !important;
}


/* =========================================================
   SUBSCRIBE
   ========================================================= */

ytd-subscribe-button-renderer
yt-button-shape button {

    background: #91c24b !important;

    color: #060706 !important;

    border: none !important;

    font-weight: 700 !important;

    box-shadow:
        0 0 10px rgba(145,194,75,.15) !important;
}


ytd-subscribe-button-renderer
yt-button-shape button:hover {

    background: #a1d458 !important;

    box-shadow:
        0 0 16px rgba(145,194,75,.25) !important;
}


/* =========================================================
   PLAYER — САМОЕ ЗАМЕТНОЕ
   ========================================================= */

/* красная линия -> зелёная */

.ytp-play-progress {

    background:
        linear-gradient(
            90deg,
            #739e38,
            #a3d55d
        ) !important;

    box-shadow:
        0 0 7px rgba(145,194,75,.35) !important;
}


/* ползунок */

.ytp-scrubber-button {

    background: #a3d55d !important;

    box-shadow:
        0 0 9px rgba(163,213,93,.45) !important;
}


/* hover controls */

.ytp-button:hover svg {

    filter:
        drop-shadow(
            0 0 3px rgba(145,194,75,.55)
        ) !important;
}


/* =========================================================
   COMMENTS
   ========================================================= */

ytd-comments {
    background: #060706 !important;
}


ytd-comment-thread-renderer {

    border-bottom:
        1px solid #121512 !important;
}


ytd-comment-renderer:hover {

    background:
        rgba(255,255,255,.008) !important;
}


/* author */

ytd-comment-renderer #author-text:hover {

    color: #9bca55 !important;
}


/* =========================================================
   SHORTS
   ========================================================= */

ytd-shorts,
ytd-reel-video-renderer {

    background: #060706 !important;
}


ytd-reel-video-renderer #actions button {

    background:
        rgba(12,14,12,.92) !important;

    border:
        1px solid #222622 !important;
}


ytd-reel-video-renderer #actions button:hover {

    background: #171a17 !important;

    border-color:
        #475b32 !important;
}


/* =========================================================
   PLAYLIST
   ========================================================= */

ytd-playlist-panel-renderer {

    background: #0b0d0b !important;

    border:
        1px solid #1c201c !important;
}


ytd-playlist-panel-video-renderer:hover {

    background: #121512 !important;
}


ytd-playlist-panel-video-renderer[selected] {

    background: #10150e !important;

    border-left:
        2px solid #91c24b !important;
}


/* =========================================================
   SCROLLBAR
   ========================================================= */

::-webkit-scrollbar {
    width: 7px !important;
}


::-webkit-scrollbar-track {
    background: #060706 !important;
}


::-webkit-scrollbar-thumb {

    background: #262a26 !important;

    border-radius: 10px !important;
}


::-webkit-scrollbar-thumb:hover {

    background: #53663c !important;
}


/* =========================================================
   SELECTION
   ========================================================= */

::selection {

    background:
        rgba(145,194,75,.28) !important;

    color: white !important;
}


/* =========================================================
   LINKS
   ========================================================= */

a:hover {

    text-decoration-color:
        #91c24b !important;
}
}
